program.compute:
options=read('/input/options')
ids=[o['id'] for o in options]
opts={o['id']:o for o in options}
from itertools import combinations
result=None
for k in range(goal['min_count'],goal['max_count']+1):
 for combo in combinations(ids,k):
  sel=list(combo)
  # Check closed dependencies: all requires in sel
  closed=True
  for cid in sel:
   for r in opts[cid]['requires']:
    if r not in sel:
     closed=False
     break
   if not closed:
    break
  if not closed:
   continue
  # Check conflicts if no_conflicts is True
  if goal['no_conflicts']:
   conflict_found=False
   for i in range(len(sel)):
    for j in range(i+1,len(sel)):
     if sel[j] in opts[sel[i]]['conflicts'] or sel[i] in opts[sel[j]]['conflicts']:
      conflict_found=True
      break
    if conflict_found:
     break
   if conflict_found:
    continue
  # Check cover tags
  cover_tags=goal['cover'].get('tags',[])
  tags_in_sel=[]
  for cid in sel:
   tags_in_sel+=opts[cid]['tags']
  if not all(t in tags_in_sel for t in cover_tags):
   continue
  # Check sum_bounds cost max
  total_cost=sum(opts[cid]['cost'] for cid in sel)
  if 'cost' in goal['sum_bounds']:
   if 'max' in goal['sum_bounds']['cost']:
    if total_cost>goal['sum_bounds']['cost']['max']:
     continue
   if 'min' in goal['sum_bounds']['cost']:
    if total_cost<goal['sum_bounds']['cost']['min']:
     continue
  # Check unique fields
  unique_fields=goal.get('unique',[])
  unique_ok=True
  for uf in unique_fields:
   vals=[opts[cid].get(uf) for cid in sel]
   if len(vals)!=len(set(vals)):
    unique_ok=False
    break
  if not unique_ok:
   continue
  # Check order_by ascending lex
  order_by=goal.get('order_by',[])
  if order_by:
   vals=[tuple(opts[cid][f] for f in order_by) for cid in sel]
   if vals!=sorted(vals):
    continue
  # Check valid
  if valid(sel):
   result=sel
   break
 if result is not None:
  break

